"use strict";window.troyServerSort=(()=>{return{versions:function(a=[],b="ASC",c="version"){const d=/^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/,e={dev:0,alpha:1,a:1,beta:2,b:2,rc:3,"#":4,pl:5,p:5,_unknown:6},f=a=>{const b=a.match(d);if(!b)return[0,0,0,0];const c=parseInt(b[1],10),f=parseInt(b[2],10),g=parseInt(b[3],10);let h=[];if(b[4]){const a=b[4].split(".");a.forEach(a=>{const b=a.match(/^[a-zA-Z]+/);if(b){const c=b[0].toLowerCase(),d=a.slice(c.length).replace(/^-+|-+$/g,"");h.push(e?.[c]||e._unknown),h.push(d?parseInt(d,10):0)}else h.push(-1)})}else h.push(7);const i=b[5]?.split(".").map(a=>parseInt(a,10))||[];return[c,f,g,...h,...i]},g="DESC"===b.toUpperCase()?-1:1;return a.sort((d,a)=>{const b=f(d[c]),e=f(a[c]);for(let c=0;c<Math.max(b.length,e.length);c++)if(b[c]!==e[c])return(b[c]-e[c])*g;return 0})}}})();